+void
+ssl_load_keyfiles(const gchar *tls_keylog_dirname, GDir *keylog_dir, GHashTable *keylog_files,
+                  const ssl_master_key_map_t *mk_map)
+{
+    /* no need to try if no key log directory is configured. */
+    if (!tls_keylog_dirname || !*tls_keylog_dirname) {
+        ssl_debug_printf("%s dtls/tls.keylog_file is not configured!\n",
+                         G_STRFUNC);
+        return;
+    }
+
+    /* Validate regexes before even trying to use it. */
+    if (!ssl_compile_keyfile_regex()) {
+        return;
+    }
+
+    ssl_debug_printf("trying to use TLS keylogs in %s\n", tls_keylog_dirname);
+
+    if (keylog_dir == NULL) {
+        keylog_dir = g_dir_open(tls_keylog_dirname, 0, NULL);
+        if (!keylog_dir) {
+            ssl_debug_printf("%s failed to open SSL keylog directory\n", G_STRFUNC);
+            return;
+        }
+    }
+
+    g_dir_rewind(keylog_dir);
+
+    const gchar *keylog_filename = NULL;
+    while ((keylog_filename = g_dir_read_name(keylog_dir)) != NULL) {
+        keylog_filename = g_build_path(G_DIR_SEPARATOR_S, tls_keylog_dirname, keylog_filename, NULL);
+
+        FILE *keylog_file = (FILE *)g_hash_table_lookup(keylog_files, keylog_filename);
+        ssl_load_keyfile(keylog_filename, &keylog_file, mk_map);
+
+        /* If the file is successfully opened, add it to the hash table. */
+        if (keylog_file) {
+            g_hash_table_insert(keylog_files, (gpointer)keylog_filename, keylog_file);
+        } else {
+            g_hash_table_remove(keylog_files, (gpointer)keylog_filename);
+        }
+    }
+}
