+                      const ssl_master_key_map_t *mk_map)
+{
+    ssl_load_keyfile(ssl_keylog_filename, keylog_file, mk_map);
+    ssl_load_keyfiles(ssl_keylog_dirname, keylog_dir, keylog_files, mk_map);
